insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-14','en-c1-14',null,5,14,'published',1,'{"id":"en-c1-14","baseId":"en-c1-14","revision":1,"level":"C1","levelIndex":5,"order":14,"title":"Register va tone: qat’iy, hurmatli yozishma","objective":"Professional e’tirozni auditoriya va munosabatga mos boshqarasiz.","context":"Register va tone: qat’iy, hurmatli yozishma","prerequisites":["en-c1-13"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Tone maqsad, munosabat va so‘ralgan amal bilan mos.","We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning.","Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang."],"pattern":"We would welcome clarification / The evidence does not support …","examples":["We would welcome clarification of the criteria.","The evidence does not support that interpretation.","We recognise the constraints on the team.","Nevertheless, the missing information affects our decision.","Could you specify the basis for the estimate?","We propose a brief meeting to resolve the issue."],"vocabulary":[{"id":"en-c1-14-v0","term":"diplomatic","meaning":"murosa ohangli","ipa":"/ˌdɪpləˈmætɪk/","collocation":"a diplomatic objection","example":"Diplomatic tone does not require pretending to agree."},{"id":"en-c1-14-v1","term":"constraint","meaning":"cheklov","ipa":"/kənˈstreɪnt/","collocation":"recognise constraints","example":"We recognise the constraints on the team."},{"id":"en-c1-14-v2","term":"basis","meaning":"asos","ipa":"/ˈbeɪsɪs/","collocation":"the basis of an estimate","example":"Could you specify the basis for the estimate?"},{"id":"en-c1-14-v3","term":"resolve","meaning":"hal qilmoq","ipa":"/rɪˈzɒlv/","collocation":"resolve a disagreement","example":"We propose a brief meeting to resolve the issue."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["We would welcome clarification / The evidence does not support …","We would welcome clarification of the criteria.","The evidence does not support that interpretation."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The estimate lacks a stated basis.","Approval depends on that missing information.","Request evidence and propose a practical discussion."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Nevertheless, the missing information affects our decision.","audio":"/english-course/v7.23/en-c1-14-dictation.mp3"},"exercises":[{"id":"en-c1-14-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: We would ___ clarification. (welcome)","answers":["welcome"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","options":["welcome","welcomes","welcoming"]},{"id":"en-c1-14-gap","type":"grammarFill","skill":"grammar","prompt":"We would ___ clarification. (welcome)","answers":["welcome"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …"},{"id":"en-c1-14-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We would welcome clarification of the criteria."],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","tokens":["We","would","welcome","clarification","of","the","criteria."]},{"id":"en-c1-14-fix","type":"correction","skill":"grammar","prompt":"As you obviously know, your estimate is wrong.","answers":["The evidence does not support the estimate; could you clarify its basis?"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …"},{"id":"en-c1-14-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["murosa ohangli","cheklov","asos","hal qilmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"We would welcome clarification / The evidence does not support …","left":["diplomatic","constraint","basis","resolve"],"options":["murosa ohangli","cheklov","asos","hal qilmoq"]},{"id":"en-c1-14-transform","type":"transformation","skill":"grammar","prompt":"Diplomatic so‘rov: Explain your estimate.","answers":["Could you specify the basis for the estimate?"],"hint":"We would welcome clarification / The evidence does not support …","explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos."},{"id":"en-c1-14-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The estimate lacks a stated basis.","Approval depends on that missing information.","Request evidence and propose a practical discussion."],"answers":["The estimate lacks a stated basis.\nApproval depends on that missing information.\nRequest evidence and propose a practical discussion."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A committee email begins, “As you obviously know, your estimate is wrong.” The writer wants clarification, but the opening attributes knowledge and fault without establishing either. A revised version recognises the team’s constraints, identifies the unsupported estimate, and asks for its basis. The objection remains firm: the missing information affects whether the committee can approve the plan. Diplomatic tone does not require pretending to agree. It separates criticism of a claim from speculation about the person making it. The editor also removes elaborate phrases that obscure the request. A professional recipient should be able to identify what is disputed, what evidence would address it, and which action is proposed next.","sentences":["A committee email begins, “As you obviously know, your estimate is wrong.","” The writer wants clarification, but the opening attributes knowledge and fault without establishing either.","A revised version recognises the team’s constraints, identifies the unsupported estimate, and asks for its basis.","The objection remains firm: the missing information affects whether the committee can approve the plan.","Diplomatic tone does not require pretending to agree.","It separates criticism of a claim from speculation about the person making it.","The editor also removes elaborate phrases that obscure the request.","A professional recipient should be able to identify what is disputed, what evidence would address it, and which action is proposed next."],"questions":[{"id":"en-c1-14-reading0","type":"choice","skill":"reading","prompt":"Birinchi opening muammosi?","answers":["unsupported attribution of knowledge and fault"],"explanation":"Motiv/kengaygan ayb.","hint":"We would welcome clarification / The evidence does not support …","options":["unsupported attribution of knowledge and fault","it asks too clearly","it names constraints"]},{"id":"en-c1-14-reading1","type":"choice","skill":"reading","prompt":"Firmness qanday saqlanadi?","answers":["state how missing evidence affects approval"],"explanation":"Amaliy qaror ta’siri.","hint":"We would welcome clarification / The evidence does not support …","options":["state how missing evidence affects approval","use stronger insults","pretend agreement"]},{"id":"en-c1-14-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"We would welcome clarification / The evidence does not support …","options":["A committee email begins, “As you obviously know, your estimate is wrong.","” The writer wants clarification, but the opening attributes knowledge and fault without establishing either.","A revised version recognises the team’s constraints, identifies the unsupported estimate, and asks for its basis.","The objection remains firm: the missing information affects whether the committee can approve the plan.","Diplomatic tone does not require pretending to agree.","It separates criticism of a claim from speculation about the person making it.","The editor also removes elaborate phrases that obscure the request.","A professional recipient should be able to identify what is disputed, what evidence would address it, and which action is proposed next."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is basis. A committee email begins, “As you obviously know, your estimate is wrong. ” The writer wants clarification, but the opening attributes knowledge and fault without establishing either. Speaker two: My main point is clarification. Challenge the estimate while asking for evidence that could resolve the issue. A committee email begins, “As you obviously know, your estimate is wrong.” The writer wants clarification, but the opening attributes knowledge and fault without establishing either. A revised version recognises the team’s constraints, identifies the unsupported estimate, and asks for its basis. The objection remains firm: the missing information affects whether the committee can approve the plan. Diplomatic tone does not require pretending to agree. It separates criticism of a claim from speculation about the person making it. The editor also removes elaborate phrases that obscure the request. A professional recipient should be able to identify what is disputed, what evidence would address it, and which action is proposed next.","audio":"/english-course/v7.23/en-c1-14.mp3","synthetic":true,"questions":[{"id":"en-c1-14-listening0","type":"choice","skill":"listening","prompt":"Birinchi opening muammosi?","answers":["unsupported attribution of knowledge and fault"],"explanation":"Motiv/kengaygan ayb.","hint":"We would welcome clarification / The evidence does not support …","options":["unsupported attribution of knowledge and fault","it asks too clearly","it names constraints"]},{"id":"en-c1-14-listening1","type":"choice","skill":"listening","prompt":"Firmness qanday saqlanadi?","answers":["state how missing evidence affects approval"],"explanation":"Amaliy qaror ta’siri.","hint":"We would welcome clarification / The evidence does not support …","options":["state how missing evidence affects approval","use stronger insults","pretend agreement"]},{"id":"en-c1-14-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["basis","clarification"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"We would welcome clarification / The evidence does not support …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-14-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Nevertheless, the missing information affects our decision."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"We would welcome clarification / The evidence does not support …","audio":"/english-course/v7.23/en-c1-14-dictation.mp3","transcript":"Nevertheless, the missing information affects our decision."}]},"writing":{"task":"Disputed estimate bo‘yicha professional email: firm objection, evidence request va next action.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear project team, we recognise the constraints involved in preparing the plan. Nevertheless, the estimate currently lacks a clear basis, and this affects whether the committee can approve the proposal. Could you specify which attendance figures and staffing assumptions were used? We would welcome clarification rather than a revised total without supporting detail. A brief meeting could help resolve the issue before Friday. Our objection concerns the evidence behind the estimate, not the team’s motives or commitment.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["We would welcome clarification of the criteria.","The evidence does not support that interpretation.","We recognise the constraints on the team."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Disputed estimate bo‘yicha professional email: firm objection, evidence request va next action. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Disputed estimate bo‘yicha professional email: firm objection, evidence request va next action.","exit":[[{"id":"en-c1-14-exit0","type":"grammarFill","skill":"grammar","prompt":"We would ___ clarification. (welcome)","answers":["welcome"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …"},{"id":"en-c1-14-exit1","type":"grammarFill","skill":"grammar","prompt":"Could you specify the ___ of the estimate?","answers":["basis"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …"},{"id":"en-c1-14-exit2","type":"grammarFill","skill":"grammar","prompt":"We propose a meeting ___ resolve it.","answers":["to"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …"},{"id":"en-c1-14-exit3","type":"choice","skill":"grammar","prompt":"Birinchi opening muammosi?","answers":["unsupported attribution of knowledge and fault"],"explanation":"Motiv/kengaygan ayb.","hint":"We would welcome clarification / The evidence does not support …","options":["unsupported attribution of knowledge and fault","it asks too clearly","it names constraints"]},{"id":"en-c1-14-exit4","type":"choice","skill":"grammar","prompt":"Firmness qanday saqlanadi?","answers":["state how missing evidence affects approval"],"explanation":"Amaliy qaror ta’siri.","hint":"We would welcome clarification / The evidence does not support …","options":["state how missing evidence affects approval","use stronger insults","pretend agreement"]}],[{"id":"en-c1-14-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The evidence does not support that interpretation."],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","tokens":["The","evidence","does","not","support","that","interpretation."]},{"id":"en-c1-14-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Could you specify the ___ of the estimate?","answers":["basis"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …"},{"id":"en-c1-14-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Nevertheless, the missing information affects our decision."],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","tokens":["Nevertheless,","the","missing","information","affects","our","decision."]},{"id":"en-c1-14-exit-b3","type":"choice","skill":"grammar","prompt":"Birinchi opening muammosi?","answers":["unsupported attribution of knowledge and fault"],"explanation":"Motiv/kengaygan ayb.","hint":"We would welcome clarification / The evidence does not support …","options":["unsupported attribution of knowledge and fault","it asks too clearly","it names constraints"]},{"id":"en-c1-14-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We propose a brief meeting to resolve the issue."],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","tokens":["We","propose","a","brief","meeting","to","resolve","the","issue."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-15','en-c1-15',null,5,15,'published',1,'{"id":"en-c1-15","baseId":"en-c1-15","revision":1,"level":"C1","levelIndex":5,"order":15,"title":"Precise vocabulary va lexical bundles","objective":"Nozik ma’no farqini va dalilga mos collocationni tanlaysiz.","context":"Precise vocabulary va lexical bundles","prerequisites":["en-c1-14"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang.","In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi.","Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring."],"pattern":"viable / efficient / equitable / in light of the evidence","examples":["The plan is viable with current staffing.","It is efficient in terms of time.","It may not be equitable for distant students.","In light of the evidence, we recommend revision.","To the extent that access improves, the trial is useful.","The issue is a matter of distribution, not total capacity."],"vocabulary":[{"id":"en-c1-15-v0","term":"viable","meaning":"amalga oshadigan","ipa":"/ˈvaɪəbəl/","collocation":"a viable plan","example":"The plan is viable with current staffing."},{"id":"en-c1-15-v1","term":"efficient","meaning":"resursni tejamli ishlatadigan","ipa":"/ɪˈfɪʃənt/","collocation":"an efficient process","example":"It is efficient in terms of time."},{"id":"en-c1-15-v2","term":"equitable","meaning":"adolatli taqsimlangan","ipa":"/ˈekwɪtəbəl/","collocation":"equitable access","example":"It may not be equitable for distant students."},{"id":"en-c1-15-v3","term":"distribution","meaning":"taqsimot","ipa":"/ˌdɪstrɪˈbjuːʃən/","collocation":"resource distribution","example":"The issue is a matter of distribution, not total capacity."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["viable / efficient / equitable / in light of the evidence","The plan is viable with current staffing.","It is efficient in terms of time."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Good hides several criteria.","Feasibility, efficiency, and equity differ.","Evaluate each criterion with matching evidence."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"In light of the evidence, we recommend revision.","audio":"/english-course/v7.23/en-c1-15-dictation.mp3"},"exercises":[{"id":"en-c1-15-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: In ___ of the evidence, revise it.","answers":["light"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","options":["light","sight","lights"]},{"id":"en-c1-15-gap","type":"grammarFill","skill":"grammar","prompt":"In ___ of the evidence, revise it.","answers":["light"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence"},{"id":"en-c1-15-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The plan is viable with current staffing."],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","tokens":["The","plan","is","viable","with","current","staffing."]},{"id":"en-c1-15-fix","type":"correction","skill":"grammar","prompt":"Efficient automatically means equitable.","answers":["An efficient plan is not necessarily equitable."],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence"},{"id":"en-c1-15-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["amalga oshadigan","resursni tejamli ishlatadigan","adolatli taqsimlangan","taqsimot"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"viable / efficient / equitable / in light of the evidence","left":["viable","efficient","equitable","distribution"],"options":["amalga oshadigan","resursni tejamli ishlatadigan","adolatli taqsimlangan","taqsimot"]},{"id":"en-c1-15-transform","type":"transformation","skill":"grammar","prompt":"Aniq mezon: The plan is good because current staff can run it.","answers":["The plan is viable with current staffing."],"hint":"viable / efficient / equitable / in light of the evidence","explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang."},{"id":"en-c1-15-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Good hides several criteria.","Feasibility, efficiency, and equity differ.","Evaluate each criterion with matching evidence."],"answers":["Good hides several criteria.\nFeasibility, efficiency, and equity differ.\nEvaluate each criterion with matching evidence."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-15-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["viable","efficient","equitable","distribution"],"options":["a viable plan","an efficient process","equitable access","resource distribution"],"answers":["a viable plan","an efficient process","equitable access","resource distribution"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The proposal is described as good, but committee members mean different things by that word. The organiser considers it viable because existing staff can run it. The finance group calls it efficient because it uses fewer hours per participant. Students ask whether it is equitable, since those living far away may still be excluded. No single adjective answers all three questions. The report adopts the separate terms and explains the criteria behind them. In light of the evidence, the committee supports a revised trial rather than a blanket endorsement. Precise vocabulary does not make the text more impressive by sounding unusual. It allows readers to see which judgement is being made, which evidence supports it, and where the judgements may conflict.","sentences":["The proposal is described as good, but committee members mean different things by that word.","The organiser considers it viable because existing staff can run it.","The finance group calls it efficient because it uses fewer hours per participant.","Students ask whether it is equitable, since those living far away may still be excluded.","No single adjective answers all three questions.","The report adopts the separate terms and explains the criteria behind them.","In light of the evidence, the committee supports a revised trial rather than a blanket endorsement.","Precise vocabulary does not make the text more impressive by sounding unusual.","It allows readers to see which judgement is being made, which evidence supports it, and where the judgements may conflict."],"questions":[{"id":"en-c1-15-reading0","type":"choice","skill":"reading","prompt":"Equitable qanday mezon?","answers":["fair distribution of access"],"explanation":"Adolatli access.","hint":"viable / efficient / equitable / in light of the evidence","options":["fair distribution of access","fewest staff hours only","technical feasibility only"]},{"id":"en-c1-15-reading1","type":"choice","skill":"reading","prompt":"Separate terms nima uchun?","answers":["the judgements can conflict"],"explanation":"Uch mezon bir xil emas.","hint":"viable / efficient / equitable / in light of the evidence","options":["the judgements can conflict","rare words are always better","all mean identical success"]},{"id":"en-c1-15-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"viable / efficient / equitable / in light of the evidence","options":["The proposal is described as good, but committee members mean different things by that word.","The organiser considers it viable because existing staff can run it.","The finance group calls it efficient because it uses fewer hours per participant.","Students ask whether it is equitable, since those living far away may still be excluded.","No single adjective answers all three questions.","The report adopts the separate terms and explains the criteria behind them.","In light of the evidence, the committee supports a revised trial rather than a blanket endorsement.","Precise vocabulary does not make the text more impressive by sounding unusual.","It allows readers to see which judgement is being made, which evidence supports it, and where the judgements may conflict."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is equitable. The proposal is described as good, but committee members mean different things by that word. The organiser considers it viable because existing staff can run it. Speaker two: My main point is criteria. State the criterion before judging whether the plan is good. The proposal is described as good, but committee members mean different things by that word. The organiser considers it viable because existing staff can run it. The finance group calls it efficient because it uses fewer hours per participant. Students ask whether it is equitable, since those living far away may still be excluded. No single adjective answers all three questions. The report adopts the separate terms and explains the criteria behind them. In light of the evidence, the committee supports a revised trial rather than a blanket endorsement. Precise vocabulary does not make the text more impressive by sounding unusual. It allows readers to see which judgement is being made, which evidence supports it, and where the judgements may conflict.","audio":"/english-course/v7.23/en-c1-15.mp3","synthetic":true,"questions":[{"id":"en-c1-15-listening0","type":"choice","skill":"listening","prompt":"Equitable qanday mezon?","answers":["fair distribution of access"],"explanation":"Adolatli access.","hint":"viable / efficient / equitable / in light of the evidence","options":["fair distribution of access","fewest staff hours only","technical feasibility only"]},{"id":"en-c1-15-listening1","type":"choice","skill":"listening","prompt":"Separate terms nima uchun?","answers":["the judgements can conflict"],"explanation":"Uch mezon bir xil emas.","hint":"viable / efficient / equitable / in light of the evidence","options":["the judgements can conflict","rare words are always better","all mean identical success"]},{"id":"en-c1-15-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["equitable","criteria"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"viable / efficient / equitable / in light of the evidence","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-15-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["In light of the evidence, we recommend revision."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"viable / efficient / equitable / in light of the evidence","audio":"/english-course/v7.23/en-c1-15-dictation.mp3","transcript":"In light of the evidence, we recommend revision."}]},"writing":{"task":"Proposalni viable/efficient/equitable mezonlarda alohida baholang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The plan appears viable with current staffing and efficient in its use of time. However, it may not be equitable for students who travel far. These judgements use different criteria and should not be combined into a general claim that the plan is good. In light of the evidence, I recommend revising the schedule and measuring participation by relevant groups. The aim is to preserve feasibility while testing whether access becomes more fairly distributed. Precise vocabulary makes the trade-off visible.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The plan is viable with current staffing.","It is efficient in terms of time.","It may not be equitable for distant students."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Proposalni viable/efficient/equitable mezonlarda alohida baholang. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Proposalni viable/efficient/equitable mezonlarda alohida baholang.","exit":[[{"id":"en-c1-15-exit0","type":"grammarFill","skill":"grammar","prompt":"In ___ of the evidence, revise it.","answers":["light"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence"},{"id":"en-c1-15-exit1","type":"grammarFill","skill":"grammar","prompt":"The plan is ___ with current staffing. (amalga oshadi)","answers":["viable"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence"},{"id":"en-c1-15-exit2","type":"grammarFill","skill":"grammar","prompt":"Access should be fairly distributed: ___.","answers":["equitable"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence"},{"id":"en-c1-15-exit3","type":"choice","skill":"grammar","prompt":"Equitable qanday mezon?","answers":["fair distribution of access"],"explanation":"Adolatli access.","hint":"viable / efficient / equitable / in light of the evidence","options":["fair distribution of access","fewest staff hours only","technical feasibility only"]},{"id":"en-c1-15-exit4","type":"choice","skill":"grammar","prompt":"Separate terms nima uchun?","answers":["the judgements can conflict"],"explanation":"Uch mezon bir xil emas.","hint":"viable / efficient / equitable / in light of the evidence","options":["the judgements can conflict","rare words are always better","all mean identical success"]}],[{"id":"en-c1-15-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["It is efficient in terms of time."],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","tokens":["It","is","efficient","in","terms","of","time."]},{"id":"en-c1-15-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The plan is ___ with current staffing. (amalga oshadi)","answers":["viable"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence"},{"id":"en-c1-15-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["In light of the evidence, we recommend revision."],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","tokens":["In","light","of","the","evidence,","we","recommend","revision."]},{"id":"en-c1-15-exit-b3","type":"choice","skill":"grammar","prompt":"Equitable qanday mezon?","answers":["fair distribution of access"],"explanation":"Adolatli access.","hint":"viable / efficient / equitable / in light of the evidence","options":["fair distribution of access","fewest staff hours only","technical feasibility only"]},{"id":"en-c1-15-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The issue is a matter of distribution, not total capacity."],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","tokens":["The","issue","is","a","matter","of","distribution,","not","total","capacity."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-16','en-c1-16',null,5,16,'published',1,'{"id":"en-c1-16","baseId":"en-c1-16","revision":1,"level":"C1","levelIndex":5,"order":16,"title":"Idiomlar: uslub va kontekst","objective":"Idiomni tushunasiz, lekin noaniq yoki nomos joyda literal ma’noni tanlaysiz.","context":"Idiomlar: uslub va kontekst","prerequisites":["en-c1-15"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi.","Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring.","Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal."],"pattern":"on the same page / a grey area / take with a pinch of salt","examples":["We need to be on the same page about the criteria.","The policy leaves a grey area.","Take the unofficial estimate with a pinch of salt.","Let us spell out the conditions.","The discussion went back to square one.","For new readers, state the meaning directly."],"vocabulary":[{"id":"en-c1-16-v0","term":"figurative","meaning":"ko‘chma","ipa":"/ˈfɪɡərətɪv/","collocation":"figurative language","example":"The revised guide states conditions directly and leaves figurative expressions for discussion where clarification can be requested."},{"id":"en-c1-16-v1","term":"literal","meaning":"to‘g‘ridan-to‘g‘ri","ipa":"/ˈlɪtərəl/","collocation":"a literal interpretation","example":"a literal interpretation"},{"id":"en-c1-16-v2","term":"ambiguity","meaning":"noaniqlik","ipa":"/ˌæmbɪˈɡjuːəti/","collocation":"avoid ambiguity","example":"avoid ambiguity"},{"id":"en-c1-16-v3","term":"idiom","meaning":"turg‘un ibora","ipa":"/ˈɪdiəm/","collocation":"a context-appropriate idiom","example":"Idioms can create a natural conversational tone and express attitudes efficiently."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["on the same page / a grey area / take with a pinch of salt","We need to be on the same page about the criteria.","The policy leaves a grey area."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["An idiom has been interpreted literally.","The guide needs exact conditions.","Choose direct language for accessible instructions."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Let us spell out the conditions.","audio":"/english-course/v7.23/en-c1-16-dictation.mp3"},"exercises":[{"id":"en-c1-16-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Be on the same ___.","answers":["page"],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt","options":["page","book","paper"]},{"id":"en-c1-16-gap","type":"grammarFill","skill":"grammar","prompt":"Be on the same ___.","answers":["page"],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt"},{"id":"en-c1-16-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We need to be on the same page about the criteria."],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt","tokens":["We","need","to","be","on","the","same","page","about","the","criteria."]},{"id":"en-c1-16-fix","type":"correction","skill":"grammar","prompt":"A grey area tells readers exactly which condition is missing.","answers":["A grey area signals uncertainty but does not specify the missing condition."],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt"},{"id":"en-c1-16-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ko‘chma","to‘g‘ridan-to‘g‘ri","noaniqlik","turg‘un ibora"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"on the same page / a grey area / take with a pinch of salt","left":["figurative","literal","ambiguity","idiom"],"options":["ko‘chma","to‘g‘ridan-to‘g‘ri","noaniqlik","turg‘un ibora"]},{"id":"en-c1-16-transform","type":"transformation","skill":"grammar","prompt":"Literal yozing: We need to be on the same page about the criteria.","answers":["We need to agree on the criteria."],"hint":"on the same page / a grey area / take with a pinch of salt","explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi."},{"id":"en-c1-16-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["An idiom has been interpreted literally.","The guide needs exact conditions.","Choose direct language for accessible instructions."],"answers":["An idiom has been interpreted literally.\nThe guide needs exact conditions.\nChoose direct language for accessible instructions."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-16-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["We need to be on the same page about the criteria."],"tokens":["We","need","to","be","on","the","same","page","about","the","criteria."],"hint":"on the same page / a grey area / take with a pinch of salt","explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi."},{"id":"en-c1-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Cohesion: reference va lexical chains: Til vositasini tanlang: Attendance rose; this ___ needs explanation. (increase)","answers":["increase"],"explanation":"This/it/they referenti yaqin va aniq bo‘lsin. Sinonimni takror uchun ishlatish tushunchani o‘zgartirmasin: attendance participationga har doim teng emas. Topic chain va reference xaritasini tekshirib, muhim atamani kerak joyda takrorlang.","hint":"attendance → this increase / the intervention → it","options":["increase","increasing","increases"],"recap":true,"sourceLesson":"Cohesion: reference va lexical chains"},{"id":"en-c1-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Register va tone: qat’iy, hurmatli yozishma: Til vositasini tanlang: We would ___ clarification. (welcome)","answers":["welcome"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","options":["welcome","welcomes","welcoming"],"recap":true,"sourceLesson":"Register va tone: qat’iy, hurmatli yozishma"},{"id":"en-c1-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Precise vocabulary va lexical bundles: Til vositasini tanlang: In ___ of the evidence, revise it.","answers":["light"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","options":["light","sight","lights"],"recap":true,"sourceLesson":"Precise vocabulary va lexical bundles"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A meeting leader says the team must be on the same page. Experienced members understand that they need shared criteria, but a new participant thinks they should open a document. The misunderstanding is harmless here, yet it shows why audience matters. Another note calls the rules a grey area without specifying what is unclear. The editor replaces the phrase with an exact description of the missing condition. Idioms can create a natural conversational tone and express attitudes efficiently. They are less useful when precision or accessibility is the main priority. Advanced language use includes knowing when not to use an idiom. The revised guide states conditions directly and leaves figurative expressions for discussion where clarification can be requested.","sentences":["A meeting leader says the team must be on the same page.","Experienced members understand that they need shared criteria, but a new participant thinks they should open a document.","The misunderstanding is harmless here, yet it shows why audience matters.","Another note calls the rules a grey area without specifying what is unclear.","The editor replaces the phrase with an exact description of the missing condition.","Idioms can create a natural conversational tone and express attitudes efficiently.","They are less useful when precision or accessibility is the main priority.","Advanced language use includes knowing when not to use an idiom.","The revised guide states conditions directly and leaves figurative expressions for discussion where clarification can be requested."],"questions":[{"id":"en-c1-16-reading0","type":"choice","skill":"reading","prompt":"New participant nega chalkashdi?","answers":["a literal interpretation"],"explanation":"Ko‘chma ma’no yangi.","hint":"on the same page / a grey area / take with a pinch of salt","options":["a literal interpretation","a wrong document page","no criteria existed"]},{"id":"en-c1-16-reading1","type":"choice","skill":"reading","prompt":"Advanced use nimani ham o‘z ichiga oladi?","answers":["choosing not to use an idiom"],"explanation":"Auditoriya/aniqlik mezoni.","hint":"on the same page / a grey area / take with a pinch of salt","options":["choosing not to use an idiom","using idioms everywhere","never speaking naturally"]},{"id":"en-c1-16-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"on the same page / a grey area / take with a pinch of salt","options":["A meeting leader says the team must be on the same page.","Experienced members understand that they need shared criteria, but a new participant thinks they should open a document.","The misunderstanding is harmless here, yet it shows why audience matters.","Another note calls the rules a grey area without specifying what is unclear.","The editor replaces the phrase with an exact description of the missing condition.","Idioms can create a natural conversational tone and express attitudes efficiently.","They are less useful when precision or accessibility is the main priority.","Advanced language use includes knowing when not to use an idiom.","The revised guide states conditions directly and leaves figurative expressions for discussion where clarification can be requested."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is literal. A meeting leader says the team must be on the same page. Experienced members understand that they need shared criteria, but a new participant thinks they should open a document. Speaker two: My main point is audience. Use direct wording when readers need exact conditions. A meeting leader says the team must be on the same page. Experienced members understand that they need shared criteria, but a new participant thinks they should open a document. The misunderstanding is harmless here, yet it shows why audience matters. Another note calls the rules a grey area without specifying what is unclear. The editor replaces the phrase with an exact description of the missing condition. Idioms can create a natural conversational tone and express attitudes efficiently. They are less useful when precision or accessibility is the main priority. Advanced language use includes knowing when not to use an idiom. The revised guide states conditions directly and leaves figurative expressions for discussion where clarification can be requested.","audio":"/english-course/v7.23/en-c1-16.mp3","synthetic":true,"questions":[{"id":"en-c1-16-listening0","type":"choice","skill":"listening","prompt":"New participant nega chalkashdi?","answers":["a literal interpretation"],"explanation":"Ko‘chma ma’no yangi.","hint":"on the same page / a grey area / take with a pinch of salt","options":["a literal interpretation","a wrong document page","no criteria existed"]},{"id":"en-c1-16-listening1","type":"choice","skill":"listening","prompt":"Advanced use nimani ham o‘z ichiga oladi?","answers":["choosing not to use an idiom"],"explanation":"Auditoriya/aniqlik mezoni.","hint":"on the same page / a grey area / take with a pinch of salt","options":["choosing not to use an idiom","using idioms everywhere","never speaking naturally"]},{"id":"en-c1-16-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["literal","audience"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"on the same page / a grey area / take with a pinch of salt","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-16-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Let us spell out the conditions."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"on the same page / a grey area / take with a pinch of salt","audio":"/english-course/v7.23/en-c1-16-dictation.mp3","transcript":"Let us spell out the conditions."}]},"writing":{"task":"Meeting dialogda idiom ishlating, keyin yangi a’zo uchun plain-language guide yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"In discussion, “on the same page” can signal the need for shared understanding. In the written guide, I would instead say that members must agree on the criteria before judging proposals. Calling the policy a grey area is also insufficient unless the missing condition is named. The revised wording explains that no deadline has been specified. This is less figurative but more accessible. Choosing direct language does not reduce sophistication; it aligns the wording with the reader’s task.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["We need to be on the same page about the criteria.","The policy leaves a grey area.","Take the unofficial estimate with a pinch of salt."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Meeting dialogda idiom ishlating, keyin yangi a’zo uchun plain-language guide yozing. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Meeting dialogda idiom ishlating, keyin yangi a’zo uchun plain-language guide yozing.","exit":[[{"id":"en-c1-16-exit0","type":"grammarFill","skill":"grammar","prompt":"Be on the same ___.","answers":["page"],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt"},{"id":"en-c1-16-exit1","type":"grammarFill","skill":"grammar","prompt":"Take it with a pinch of ___.","answers":["salt"],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt"},{"id":"en-c1-16-exit2","type":"grammarFill","skill":"grammar","prompt":"Spell ___ the conditions.","answers":["out"],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt"},{"id":"en-c1-16-exit3","type":"choice","skill":"grammar","prompt":"New participant nega chalkashdi?","answers":["a literal interpretation"],"explanation":"Ko‘chma ma’no yangi.","hint":"on the same page / a grey area / take with a pinch of salt","options":["a literal interpretation","a wrong document page","no criteria existed"]},{"id":"en-c1-16-exit4","type":"choice","skill":"grammar","prompt":"Advanced use nimani ham o‘z ichiga oladi?","answers":["choosing not to use an idiom"],"explanation":"Auditoriya/aniqlik mezoni.","hint":"on the same page / a grey area / take with a pinch of salt","options":["choosing not to use an idiom","using idioms everywhere","never speaking naturally"]}],[{"id":"en-c1-16-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The policy leaves a grey area."],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt","tokens":["The","policy","leaves","a","grey","area."]},{"id":"en-c1-16-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Take it with a pinch of ___.","answers":["salt"],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt"},{"id":"en-c1-16-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Let us spell out the conditions."],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt","tokens":["Let","us","spell","out","the","conditions."]},{"id":"en-c1-16-exit-b3","type":"choice","skill":"grammar","prompt":"New participant nega chalkashdi?","answers":["a literal interpretation"],"explanation":"Ko‘chma ma’no yangi.","hint":"on the same page / a grey area / take with a pinch of salt","options":["a literal interpretation","a wrong document page","no criteria existed"]},{"id":"en-c1-16-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["For new readers, state the meaning directly."],"explanation":"On the same page, a grey area, take with a pinch of salt kontekstda ma’no oladi. Idiom literal tarjima bilan ochilmasligi mumkin; auditoriyaga mosligini tekshiring. Professional safety yoki aniq yo‘riqnomada figurative ibora o‘rniga oddiy aniq gap afzal.","hint":"on the same page / a grey area / take with a pinch of salt","tokens":["For","new","readers,","state","the","meaning","directly."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-c1-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Cohesion: reference va lexical chains: Til vositasini tanlang: Attendance rose; this ___ needs explanation. (increase)","answers":["increase"],"explanation":"This/it/they referenti yaqin va aniq bo‘lsin. Sinonimni takror uchun ishlatish tushunchani o‘zgartirmasin: attendance participationga har doim teng emas. Topic chain va reference xaritasini tekshirib, muhim atamani kerak joyda takrorlang.","hint":"attendance → this increase / the intervention → it","options":["increase","increasing","increases"],"recap":true,"sourceLesson":"Cohesion: reference va lexical chains"},{"id":"en-c1-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Register va tone: qat’iy, hurmatli yozishma: Til vositasini tanlang: We would ___ clarification. (welcome)","answers":["welcome"],"explanation":"Tone maqsad, munosabat va so‘ralgan amal bilan mos. We would welcome clarification qat’iy savolni hurmatli qiladi; passiv agressiv taxmindan saqlaning. Formal register uzunlik emas: aniq noun/verb va chegaralangan claim tanlang.","hint":"We would welcome clarification / The evidence does not support …","options":["welcome","welcomes","welcoming"],"recap":true,"sourceLesson":"Register va tone: qat’iy, hurmatli yozishma"},{"id":"en-c1-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Precise vocabulary va lexical bundles: Til vositasini tanlang: In ___ of the evidence, revise it.","answers":["light"],"explanation":"Viable, efficient, equitable turli mezonlar; barchasini good deb almashtirmang. In light of, to the extent that, a matter of lexical bundles munosabatni aniq beradi. Aniq so‘z kamyob so‘z degani emas; kontekst va collocationni tekshiring.","hint":"viable / efficient / equitable / in light of the evidence","options":["light","sight","lights"],"recap":true,"sourceLesson":"Precise vocabulary va lexical bundles"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-17','en-c1-17',null,5,17,'published',1,'{"id":"en-c1-17","baseId":"en-c1-17","revision":1,"level":"C1","levelIndex":5,"order":17,"title":"Paraphrasing: ma’no chegarasi","objective":"Manba da’vosini kuchaytirmasdan boshqa so‘zlarda ifodalaysiz.","context":"Paraphrasing: ma’no chegarasi","prerequisites":["en-c1-16"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Paraphrase mazmun, scope, attribution va certaintyni saqlaydi.","Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas.","May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi."],"pattern":"may contribute → could play a part / some → a subset","examples":["The programme may contribute to confidence.","The programme could play a part in greater confidence.","Some participants reported a benefit.","A subset of participants described an improvement.","The report does not establish a cause.","The paraphrase must preserve that limitation."],"vocabulary":[{"id":"en-c1-17-v0","term":"fidelity","meaning":"mazmunga sodiqlik","ipa":"/fɪˈdeləti/","collocation":"semantic fidelity","example":"semantic fidelity"},{"id":"en-c1-17-v1","term":"distortion","meaning":"mazmun buzilishi","ipa":"/dɪˈstɔːʃən/","collocation":"avoid distortion","example":"avoid distortion"},{"id":"en-c1-17-v2","term":"qualification","meaning":"cheklov","ipa":"/ˌkwɒlɪfɪˈkeɪʃən/","collocation":"retain a qualification","example":"The shorter wording removes three qualifications: possibility, contribution rather than sole causation, and a limited group."},{"id":"en-c1-17-v3","term":"acknowledge","meaning":"tan olib ko‘rsatmoq","ipa":"/əkˈnɒlɪdʒ/","collocation":"acknowledge a source","example":"acknowledge a source"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["may contribute → could play a part / some → a subset","The programme may contribute to confidence.","The programme could play a part in greater confidence."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The source contains three limitations.","The draft removes them.","Restore scope, certainty, and attribution."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"A subset of participants described an improvement.","audio":"/english-course/v7.23/en-c1-17-dictation.mp3"},"exercises":[{"id":"en-c1-17-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The programme may ___ to confidence. (contribute)","answers":["contribute"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","options":["contribute","contributes","contributed"]},{"id":"en-c1-17-gap","type":"grammarFill","skill":"grammar","prompt":"The programme may ___ to confidence. (contribute)","answers":["contribute"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset"},{"id":"en-c1-17-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The programme may contribute to confidence."],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","tokens":["The","programme","may","contribute","to","confidence."]},{"id":"en-c1-17-fix","type":"correction","skill":"grammar","prompt":"Some participants may benefit means all students definitely benefit.","answers":["Some participants may benefit does not establish that all students definitely benefit."],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset"},{"id":"en-c1-17-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["mazmunga sodiqlik","mazmun buzilishi","cheklov","tan olib ko‘rsatmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"may contribute → could play a part / some → a subset","left":["fidelity","distortion","qualification","acknowledge"],"options":["mazmunga sodiqlik","mazmun buzilishi","cheklov","tan olib ko‘rsatmoq"]},{"id":"en-c1-17-transform","type":"paraphrase","skill":"grammar","prompt":"Faithful paraphrase: The programme may contribute to confidence.","answers":["The programme could play a part in greater confidence."],"hint":"may contribute → could play a part / some → a subset","explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi."},{"id":"en-c1-17-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The source contains three limitations.","The draft removes them.","Restore scope, certainty, and attribution."],"answers":["The source contains three limitations.\nThe draft removes them.\nRestore scope, certainty, and attribution."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The source says that the programme may contribute to confidence among some participants. A draft paraphrase says that it makes students confident. The shorter wording removes three qualifications: possibility, contribution rather than sole causation, and a limited group. A faithful paraphrase can change structure and vocabulary while retaining those boundaries. The editor writes that the programme could play a part in greater confidence for a subset of participants. She also attributes the claim to the report rather than presenting it as her own established finding. The purpose is not to preserve every word. It is to preserve the claim the words make. Checking scope and certainty is therefore as important as avoiding copied phrasing.","sentences":["The source says that the programme may contribute to confidence among some participants.","A draft paraphrase says that it makes students confident.","The shorter wording removes three qualifications: possibility, contribution rather than sole causation, and a limited group.","A faithful paraphrase can change structure and vocabulary while retaining those boundaries.","The editor writes that the programme could play a part in greater confidence for a subset of participants.","She also attributes the claim to the report rather than presenting it as her own established finding.","The purpose is not to preserve every word.","It is to preserve the claim the words make.","Checking scope and certainty is therefore as important as avoiding copied phrasing."],"questions":[{"id":"en-c1-17-reading0","type":"choice","skill":"reading","prompt":"Draft nima yo‘qotdi?","answers":["possibility, contribution, and limited scope"],"explanation":"Uch qualification.","hint":"may contribute → could play a part / some → a subset","options":["possibility, contribution, and limited scope","only spelling","the programme name only"]},{"id":"en-c1-17-reading1","type":"choice","skill":"reading","prompt":"Faithful paraphrase nima saqlaydi?","answers":["claim boundaries and attribution"],"explanation":"Ma’no/ishonch/qamrov.","hint":"may contribute → could play a part / some → a subset","options":["claim boundaries and attribution","every original word","only sentence length"]},{"id":"en-c1-17-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"may contribute → could play a part / some → a subset","options":["The source says that the programme may contribute to confidence among some participants.","A draft paraphrase says that it makes students confident.","The shorter wording removes three qualifications: possibility, contribution rather than sole causation, and a limited group.","A faithful paraphrase can change structure and vocabulary while retaining those boundaries.","The editor writes that the programme could play a part in greater confidence for a subset of participants.","She also attributes the claim to the report rather than presenting it as her own established finding.","The purpose is not to preserve every word.","It is to preserve the claim the words make.","Checking scope and certainty is therefore as important as avoiding copied phrasing."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is qualification. The source says that the programme may contribute to confidence among some participants. A draft paraphrase says that it makes students confident. Speaker two: My main point is fidelity. Change the wording while retaining the limits of the claim. The source says that the programme may contribute to confidence among some participants. A draft paraphrase says that it makes students confident. The shorter wording removes three qualifications: possibility, contribution rather than sole causation, and a limited group. A faithful paraphrase can change structure and vocabulary while retaining those boundaries. The editor writes that the programme could play a part in greater confidence for a subset of participants. She also attributes the claim to the report rather than presenting it as her own established finding. The purpose is not to preserve every word. It is to preserve the claim the words make. Checking scope and certainty is therefore as important as avoiding copied phrasing.","audio":"/english-course/v7.23/en-c1-17.mp3","synthetic":true,"questions":[{"id":"en-c1-17-listening0","type":"choice","skill":"listening","prompt":"Draft nima yo‘qotdi?","answers":["possibility, contribution, and limited scope"],"explanation":"Uch qualification.","hint":"may contribute → could play a part / some → a subset","options":["possibility, contribution, and limited scope","only spelling","the programme name only"]},{"id":"en-c1-17-listening1","type":"choice","skill":"listening","prompt":"Faithful paraphrase nima saqlaydi?","answers":["claim boundaries and attribution"],"explanation":"Ma’no/ishonch/qamrov.","hint":"may contribute → could play a part / some → a subset","options":["claim boundaries and attribution","every original word","only sentence length"]},{"id":"en-c1-17-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["qualification","fidelity"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"may contribute → could play a part / some → a subset","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-17-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["A subset of participants described an improvement."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"may contribute → could play a part / some → a subset","audio":"/english-course/v7.23/en-c1-17-dictation.mp3","transcript":"A subset of participants described an improvement."}]},"writing":{"task":"Uch source gapni paraphrase qiling; scope, certainty va attribution jadvali tuzing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"According to the report, the programme could play a part in greater confidence for a subset of participants. This paraphrase retains the original possibility and does not turn contribution into sole causation. It also preserves the limited scope rather than referring to all students. The report’s claim remains attributed to its source. In revision, I check those boundaries before choosing alternative words. A shorter sentence is not a faithful paraphrase if it removes the qualifications that define the original meaning.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The programme may contribute to confidence.","The programme could play a part in greater confidence.","Some participants reported a benefit."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Uch source gapni paraphrase qiling; scope, certainty va attribution jadvali tuzing. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Uch source gapni paraphrase qiling; scope, certainty va attribution jadvali tuzing.","exit":[[{"id":"en-c1-17-exit0","type":"grammarFill","skill":"grammar","prompt":"The programme may ___ to confidence. (contribute)","answers":["contribute"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset"},{"id":"en-c1-17-exit1","type":"grammarFill","skill":"grammar","prompt":"It could play a ___ in improvement.","answers":["part"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset"},{"id":"en-c1-17-exit2","type":"grammarFill","skill":"grammar","prompt":"A ___ of participants reported benefit. (kichik qism)","answers":["subset"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset"},{"id":"en-c1-17-exit3","type":"choice","skill":"grammar","prompt":"Draft nima yo‘qotdi?","answers":["possibility, contribution, and limited scope"],"explanation":"Uch qualification.","hint":"may contribute → could play a part / some → a subset","options":["possibility, contribution, and limited scope","only spelling","the programme name only"]},{"id":"en-c1-17-exit4","type":"choice","skill":"grammar","prompt":"Faithful paraphrase nima saqlaydi?","answers":["claim boundaries and attribution"],"explanation":"Ma’no/ishonch/qamrov.","hint":"may contribute → could play a part / some → a subset","options":["claim boundaries and attribution","every original word","only sentence length"]}],[{"id":"en-c1-17-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The programme could play a part in greater confidence."],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","tokens":["The","programme","could","play","a","part","in","greater","confidence."]},{"id":"en-c1-17-exit-b1","type":"grammarFill","skill":"grammar","prompt":"It could play a ___ in improvement.","answers":["part"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset"},{"id":"en-c1-17-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["A subset of participants described an improvement."],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","tokens":["A","subset","of","participants","described","an","improvement."]},{"id":"en-c1-17-exit-b3","type":"choice","skill":"grammar","prompt":"Draft nima yo‘qotdi?","answers":["possibility, contribution, and limited scope"],"explanation":"Uch qualification.","hint":"may contribute → could play a part / some → a subset","options":["possibility, contribution, and limited scope","only spelling","the programme name only"]},{"id":"en-c1-17-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The paraphrase must preserve that limitation."],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","tokens":["The","paraphrase","must","preserve","that","limitation."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-18','en-c1-18',null,5,18,'published',1,'{"id":"en-c1-18","baseId":"en-c1-18","revision":1,"level":"C1","levelIndex":5,"order":18,"title":"Summarising va synthesis","objective":"Ikki manbaning mos va ziddiyatli qismlarini xolis birlashtirasiz.","context":"Summarising va synthesis","prerequisites":["en-c1-17"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi.","Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin.","Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang."],"pattern":"Source A … whereas Source B … / taken together …","examples":["The survey reports a general preference.","The interviews describe individual constraints.","These findings are not necessarily contradictory.","Taken together, they suggest a mixed approach.","Neither source measures long-term attendance.","A synthesis should retain that shared limitation."],"vocabulary":[{"id":"en-c1-18-v0","term":"synthesis","meaning":"birlashtiruvchi tahlil","ipa":"/ˈsɪnθəsɪs/","collocation":"develop a synthesis","example":"A synthesis should retain that shared limitation."},{"id":"en-c1-18-v1","term":"converge","meaning":"moslashmoq","ipa":"/kənˈvɜːdʒ/","collocation":"findings converge","example":"findings converge"},{"id":"en-c1-18-v2","term":"diverge","meaning":"farqlashmoq","ipa":"/daɪˈvɜːdʒ/","collocation":"findings diverge","example":"findings diverge"},{"id":"en-c1-18-v3","term":"methodology","meaning":"tadqiqot usuli","ipa":"/ˌmeθəˈdɒlədʒi/","collocation":"compare methodology","example":"compare methodology"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Source A … whereas Source B … / taken together …","The survey reports a general preference.","The interviews describe individual constraints."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The sources address different questions.","Preference and constraints are both relevant.","Integrate them while retaining the shared limitation."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Taken together, they suggest a mixed approach.","audio":"/english-course/v7.23/en-c1-18-dictation.mp3"},"exercises":[{"id":"en-c1-18-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Taken ___, they suggest a mixed approach.","answers":["together"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","options":["together","combines","combining"]},{"id":"en-c1-18-gap","type":"grammarFill","skill":"grammar","prompt":"Taken ___, they suggest a mixed approach.","answers":["together"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …"},{"id":"en-c1-18-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The survey reports a general preference."],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","tokens":["The","survey","reports","a","general","preference."]},{"id":"en-c1-18-fix","type":"correction","skill":"grammar","prompt":"The larger survey automatically makes the interviews irrelevant.","answers":["The larger survey and the interviews provide different relevant evidence."],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …"},{"id":"en-c1-18-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["birlashtiruvchi tahlil","moslashmoq","farqlashmoq","tadqiqot usuli"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Source A … whereas Source B … / taken together …","left":["synthesis","converge","diverge","methodology"],"options":["birlashtiruvchi tahlil","moslashmoq","farqlashmoq","tadqiqot usuli"]},{"id":"en-c1-18-transform","type":"transformation","skill":"grammar","prompt":"Integrate: The survey measures preference. The interviews explain constraints.","answers":["The survey measures preference, whereas the interviews explain constraints."],"hint":"Source A … whereas Source B … / taken together …","explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi."},{"id":"en-c1-18-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The sources address different questions.","Preference and constraints are both relevant.","Integrate them while retaining the shared limitation."],"answers":["The sources address different questions.\nPreference and constraints are both relevant.\nIntegrate them while retaining the shared limitation."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-18-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["synthesis","converge","diverge","methodology"],"options":["develop a synthesis","findings converge","findings diverge","compare methodology"],"answers":["develop a synthesis","findings converge","findings diverge","compare methodology"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Source A is a survey of sixty students that favours a fixed afternoon session. Source B contains interviews with six students who travel far; they describe difficulties attending on that day. Calling the sources contradictory overlooks the different questions they answer. The survey records preference across a wider group, while the interviews explain constraints for a particular group. Taken together, the sources support testing a mixed schedule, but neither measures long-term attendance. A synthesis should not choose one source simply because it has more respondents or more detailed stories. It compares scope, method, and relevance to the decision. The conclusion can integrate both forms of evidence while keeping the shared limitation visible.","sentences":["Source A is a survey of sixty students that favours a fixed afternoon session.","Source B contains interviews with six students who travel far; they describe difficulties attending on that day.","Calling the sources contradictory overlooks the different questions they answer.","The survey records preference across a wider group, while the interviews explain constraints for a particular group.","Taken together, the sources support testing a mixed schedule, but neither measures long-term attendance.","A synthesis should not choose one source simply because it has more respondents or more detailed stories.","It compares scope, method, and relevance to the decision.","The conclusion can integrate both forms of evidence while keeping the shared limitation visible."],"questions":[{"id":"en-c1-18-reading0","type":"choice","skill":"reading","prompt":"Sources nega shartli zid emas?","answers":["they answer different questions"],"explanation":"Population va maqsad boshqa.","hint":"Source A … whereas Source B … / taken together …","options":["they answer different questions","both have sixty people","interviews measure all attendance"]},{"id":"en-c1-18-reading1","type":"choice","skill":"reading","prompt":"Ikkalasining cheklovi?","answers":["no long-term attendance measure"],"explanation":"Shared limitation.","hint":"Source A … whereas Source B … / taken together …","options":["no long-term attendance measure","no student responses","no preference evidence"]},{"id":"en-c1-18-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Source A … whereas Source B … / taken together …","options":["Source A is a survey of sixty students that favours a fixed afternoon session.","Source B contains interviews with six students who travel far; they describe difficulties attending on that day.","Calling the sources contradictory overlooks the different questions they answer.","The survey records preference across a wider group, while the interviews explain constraints for a particular group.","Taken together, the sources support testing a mixed schedule, but neither measures long-term attendance.","A synthesis should not choose one source simply because it has more respondents or more detailed stories.","It compares scope, method, and relevance to the decision.","The conclusion can integrate both forms of evidence while keeping the shared limitation visible."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is methodology. Source A is a survey of sixty students that favours a fixed afternoon session. Source B contains interviews with six students who travel far; they describe difficulties attending on that day. Speaker two: My main point is synthesis. Compare scope and method instead of ranking sources by size alone. Source A is a survey of sixty students that favours a fixed afternoon session. Source B contains interviews with six students who travel far; they describe difficulties attending on that day. Calling the sources contradictory overlooks the different questions they answer. The survey records preference across a wider group, while the interviews explain constraints for a particular group. Taken together, the sources support testing a mixed schedule, but neither measures long-term attendance. A synthesis should not choose one source simply because it has more respondents or more detailed stories. It compares scope, method, and relevance to the decision. The conclusion can integrate both forms of evidence while keeping the shared limitation visible.","audio":"/english-course/v7.23/en-c1-18.mp3","synthetic":true,"questions":[{"id":"en-c1-18-listening0","type":"choice","skill":"listening","prompt":"Sources nega shartli zid emas?","answers":["they answer different questions"],"explanation":"Population va maqsad boshqa.","hint":"Source A … whereas Source B … / taken together …","options":["they answer different questions","both have sixty people","interviews measure all attendance"]},{"id":"en-c1-18-listening1","type":"choice","skill":"listening","prompt":"Ikkalasining cheklovi?","answers":["no long-term attendance measure"],"explanation":"Shared limitation.","hint":"Source A … whereas Source B … / taken together …","options":["no long-term attendance measure","no student responses","no preference evidence"]},{"id":"en-c1-18-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["methodology","synthesis"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Source A … whereas Source B … / taken together …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-18-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Taken together, they suggest a mixed approach."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Source A … whereas Source B … / taken together …","audio":"/english-course/v7.23/en-c1-18-dictation.mp3","transcript":"Taken together, they suggest a mixed approach."}]},"writing":{"task":"Survey va interview uchun integrated synthesis: convergence, difference va shared limitation.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The survey favours a fixed afternoon, whereas interviews with distant students identify constraints on attending that day. These findings are not necessarily contradictory because the sources address different aspects of the decision. Taken together, they support testing a schedule that balances general preference with access needs. Neither source measures long-term attendance, so the recommendation remains provisional. A synthesis should explain how the evidence relates rather than select one source merely because it is larger or more detailed.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The survey reports a general preference.","The interviews describe individual constraints.","These findings are not necessarily contradictory."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Survey va interview uchun integrated synthesis: convergence, difference va shared limitation. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Survey va interview uchun integrated synthesis: convergence, difference va shared limitation.","exit":[[{"id":"en-c1-18-exit0","type":"grammarFill","skill":"grammar","prompt":"Taken ___, they suggest a mixed approach.","answers":["together"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …"},{"id":"en-c1-18-exit1","type":"grammarFill","skill":"grammar","prompt":"Neither source ___ long-term attendance. (measure)","answers":["measures"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …"},{"id":"en-c1-18-exit2","type":"grammarFill","skill":"grammar","prompt":"The findings are not necessarily ___. (contradictory)","answers":["contradictory"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …"},{"id":"en-c1-18-exit3","type":"choice","skill":"grammar","prompt":"Sources nega shartli zid emas?","answers":["they answer different questions"],"explanation":"Population va maqsad boshqa.","hint":"Source A … whereas Source B … / taken together …","options":["they answer different questions","both have sixty people","interviews measure all attendance"]},{"id":"en-c1-18-exit4","type":"choice","skill":"grammar","prompt":"Ikkalasining cheklovi?","answers":["no long-term attendance measure"],"explanation":"Shared limitation.","hint":"Source A … whereas Source B … / taken together …","options":["no long-term attendance measure","no student responses","no preference evidence"]}],[{"id":"en-c1-18-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The interviews describe individual constraints."],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","tokens":["The","interviews","describe","individual","constraints."]},{"id":"en-c1-18-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Neither source ___ long-term attendance. (measure)","answers":["measures"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …"},{"id":"en-c1-18-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Taken together, they suggest a mixed approach."],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","tokens":["Taken","together,","they","suggest","a","mixed","approach."]},{"id":"en-c1-18-exit-b3","type":"choice","skill":"grammar","prompt":"Sources nega shartli zid emas?","answers":["they answer different questions"],"explanation":"Population va maqsad boshqa.","hint":"Source A … whereas Source B … / taken together …","options":["they answer different questions","both have sixty people","interviews measure all attendance"]},{"id":"en-c1-18-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["A synthesis should retain that shared limitation."],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","tokens":["A","synthesis","should","retain","that","shared","limitation."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-19','en-c1-19',null,5,19,'published',1,'{"id":"en-c1-19","baseId":"en-c1-19","revision":1,"level":"C1","levelIndex":5,"order":19,"title":"Argument evaluation: premise va xulosa","objective":"Dalildan xulosaga o‘tishdagi yashirin farazni aniqlaysiz.","context":"Argument evaluation: premise va xulosa","prerequisites":["en-c1-18"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi.","Popularity effectivenessga, correlation causationga avtomatik dalil emas.","Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling."],"pattern":"premise → inference → conclusion / assumption → test","examples":["The argument assumes that attendance indicates benefit.","That premise needs independent support.","A popular programme is not necessarily effective.","The counterexample narrows the conclusion.","We should distinguish validity from truth.","The recommendation follows only if the assumption holds."],"vocabulary":[{"id":"en-c1-19-v0","term":"premise","meaning":"asos faraz","ipa":"/ˈpremɪs/","collocation":"an unsupported premise","example":"That premise needs independent support."},{"id":"en-c1-19-v1","term":"validity","meaning":"mantiqiy to‘g‘rilik","ipa":"/vəˈlɪdəti/","collocation":"test validity","example":"We should distinguish validity from truth."},{"id":"en-c1-19-v2","term":"counterexample","meaning":"qarshi misol","ipa":"/ˈkaʊntərɪɡˌzɑːmpəl/","collocation":"consider a counterexample","example":"The counterexample narrows the conclusion."},{"id":"en-c1-19-v3","term":"warrant","meaning":"xulosaga asos","ipa":"/ˈwɒrənt/","collocation":"the inferential warrant","example":"the inferential warrant"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["premise → inference → conclusion / assumption → test","The argument assumes that attendance indicates benefit.","That premise needs independent support."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Popularity is observed.","Learning benefit is assumed.","Test the link before accepting the conclusion."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The counterexample narrows the conclusion.","audio":"/english-course/v7.23/en-c1-19-dictation.mp3"},"exercises":[{"id":"en-c1-19-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: A popular programme is not necessarily ___.","answers":["effective"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","options":["effective","effectiveness","effectively"]},{"id":"en-c1-19-gap","type":"grammarFill","skill":"grammar","prompt":"A popular programme is not necessarily ___.","answers":["effective"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test"},{"id":"en-c1-19-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The argument assumes that attendance indicates benefit."],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","tokens":["The","argument","assumes","that","attendance","indicates","benefit."]},{"id":"en-c1-19-fix","type":"correction","skill":"grammar","prompt":"Popularity proves learning, and questioning it proves failure.","answers":["Popularity does not establish learning, and questioning the inference does not prove failure."],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test"},{"id":"en-c1-19-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["asos faraz","mantiqiy to‘g‘rilik","qarshi misol","xulosaga asos"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"premise → inference → conclusion / assumption → test","left":["premise","validity","counterexample","warrant"],"options":["asos faraz","mantiqiy to‘g‘rilik","qarshi misol","xulosaga asos"]},{"id":"en-c1-19-transform","type":"transformation","skill":"grammar","prompt":"Assumptionni oching: Many attend, therefore learning improves.","answers":["The argument assumes that attendance indicates learning benefit."],"hint":"premise → inference → conclusion / assumption → test","explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi."},{"id":"en-c1-19-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Popularity is observed.","Learning benefit is assumed.","Test the link before accepting the conclusion."],"answers":["Popularity is observed.\nLearning benefit is assumed.\nTest the link before accepting the conclusion."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The proposal argues that the club is popular, so it must improve learning. Its evidence supports popularity, but the conclusion requires an additional premise: participation must produce the intended learning benefit. That premise has not been tested. A counterexample is possible: a popular activity can be enjoyable without improving the target skill. This does not prove the club is ineffective. It shows that the argument is incomplete. The committee asks for a measure of what participants can do before and after the programme, with relevant comparison evidence. Evaluating an argument therefore involves neither automatic acceptance nor automatic rejection. It identifies what would make the inference stronger and which claims remain unsupported.","sentences":["The proposal argues that the club is popular, so it must improve learning.","Its evidence supports popularity, but the conclusion requires an additional premise: participation must produce the intended learning benefit.","That premise has not been tested.","A counterexample is possible: a popular activity can be enjoyable without improving the target skill.","This does not prove the club is ineffective.","It shows that the argument is incomplete.","The committee asks for a measure of what participants can do before and after the programme, with relevant comparison evidence.","Evaluating an argument therefore involves neither automatic acceptance nor automatic rejection.","It identifies what would make the inference stronger and which claims remain unsupported."],"questions":[{"id":"en-c1-19-reading0","type":"choice","skill":"reading","prompt":"Yashirin premise?","answers":["participation produces learning benefit"],"explanation":"Popularity→learning uchun qo‘shimcha faraz.","hint":"premise → inference → conclusion / assumption → test","options":["participation produces learning benefit","the club is unpopular","all fun is harmful"]},{"id":"en-c1-19-reading1","type":"choice","skill":"reading","prompt":"Counterexample nima isbotlaydi?","answers":["the inference needs support"],"explanation":"Argument incomplete, opposite proof emas.","hint":"premise → inference → conclusion / assumption → test","options":["the inference needs support","the club is definitely ineffective","nobody enjoys it"]},{"id":"en-c1-19-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"premise → inference → conclusion / assumption → test","options":["The proposal argues that the club is popular, so it must improve learning.","Its evidence supports popularity, but the conclusion requires an additional premise: participation must produce the intended learning benefit.","That premise has not been tested.","A counterexample is possible: a popular activity can be enjoyable without improving the target skill.","This does not prove the club is ineffective.","It shows that the argument is incomplete.","The committee asks for a measure of what participants can do before and after the programme, with relevant comparison evidence.","Evaluating an argument therefore involves neither automatic acceptance nor automatic rejection.","It identifies what would make the inference stronger and which claims remain unsupported."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is premise. The proposal argues that the club is popular, so it must improve learning. Its evidence supports popularity, but the conclusion requires an additional premise: participation must produce the intended learning benefit. Speaker two: My main point is warrant. Ask what connects the popularity evidence to the learning conclusion. The proposal argues that the club is popular, so it must improve learning. Its evidence supports popularity, but the conclusion requires an additional premise: participation must produce the intended learning benefit. That premise has not been tested. A counterexample is possible: a popular activity can be enjoyable without improving the target skill. This does not prove the club is ineffective. It shows that the argument is incomplete. The committee asks for a measure of what participants can do before and after the programme, with relevant comparison evidence. Evaluating an argument therefore involves neither automatic acceptance nor automatic rejection. It identifies what would make the inference stronger and which claims remain unsupported.","audio":"/english-course/v7.23/en-c1-19.mp3","synthetic":true,"questions":[{"id":"en-c1-19-listening0","type":"choice","skill":"listening","prompt":"Yashirin premise?","answers":["participation produces learning benefit"],"explanation":"Popularity→learning uchun qo‘shimcha faraz.","hint":"premise → inference → conclusion / assumption → test","options":["participation produces learning benefit","the club is unpopular","all fun is harmful"]},{"id":"en-c1-19-listening1","type":"choice","skill":"listening","prompt":"Counterexample nima isbotlaydi?","answers":["the inference needs support"],"explanation":"Argument incomplete, opposite proof emas.","hint":"premise → inference → conclusion / assumption → test","options":["the inference needs support","the club is definitely ineffective","nobody enjoys it"]},{"id":"en-c1-19-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["premise","warrant"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"premise → inference → conclusion / assumption → test","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-19-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The counterexample narrows the conclusion."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"premise → inference → conclusion / assumption → test","audio":"/english-course/v7.23/en-c1-19-dictation.mp3","transcript":"The counterexample narrows the conclusion."}]},"writing":{"task":"Argument evaluation: premise, warrant, counterexample va kerakli dalilni yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The proposal establishes that the club is popular, but its learning conclusion depends on an untested premise. Participation may be enjoyable without producing the target skill. This counterexample shows that popularity alone is insufficient; it does not establish that the club is ineffective. I recommend measuring what participants can do before and after the programme and considering relevant comparison evidence. The aim is to strengthen the inference rather than replace an unsupported positive claim with an equally unsupported negative one.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The argument assumes that attendance indicates benefit.","That premise needs independent support.","A popular programme is not necessarily effective."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Argument evaluation: premise, warrant, counterexample va kerakli dalilni yozing. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Argument evaluation: premise, warrant, counterexample va kerakli dalilni yozing.","exit":[[{"id":"en-c1-19-exit0","type":"grammarFill","skill":"grammar","prompt":"A popular programme is not necessarily ___.","answers":["effective"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test"},{"id":"en-c1-19-exit1","type":"grammarFill","skill":"grammar","prompt":"The premise needs independent ___.","answers":["support"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test"},{"id":"en-c1-19-exit2","type":"grammarFill","skill":"grammar","prompt":"The conclusion follows only ___ the assumption holds.","answers":["if"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test"},{"id":"en-c1-19-exit3","type":"choice","skill":"grammar","prompt":"Yashirin premise?","answers":["participation produces learning benefit"],"explanation":"Popularity→learning uchun qo‘shimcha faraz.","hint":"premise → inference → conclusion / assumption → test","options":["participation produces learning benefit","the club is unpopular","all fun is harmful"]},{"id":"en-c1-19-exit4","type":"choice","skill":"grammar","prompt":"Counterexample nima isbotlaydi?","answers":["the inference needs support"],"explanation":"Argument incomplete, opposite proof emas.","hint":"premise → inference → conclusion / assumption → test","options":["the inference needs support","the club is definitely ineffective","nobody enjoys it"]}],[{"id":"en-c1-19-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["That premise needs independent support."],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","tokens":["That","premise","needs","independent","support."]},{"id":"en-c1-19-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The premise needs independent ___.","answers":["support"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test"},{"id":"en-c1-19-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The counterexample narrows the conclusion."],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","tokens":["The","counterexample","narrows","the","conclusion."]},{"id":"en-c1-19-exit-b3","type":"choice","skill":"grammar","prompt":"Yashirin premise?","answers":["participation produces learning benefit"],"explanation":"Popularity→learning uchun qo‘shimcha faraz.","hint":"premise → inference → conclusion / assumption → test","options":["participation produces learning benefit","the club is unpopular","all fun is harmful"]},{"id":"en-c1-19-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The recommendation follows only if the assumption holds."],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","tokens":["The","recommendation","follows","only","if","the","assumption","holds."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-19",